//==============================================================================
//
// File:		LDrawLSynth.swift
//
// Purpose:		A container directive representing LSynth bendable parts such as pipes,
//              tubes, string, chains and treads.  This class manages the constraints
//              used by LSynth, as well as the synthesized parts generated by LSynth.
//
//  Created by Robin Macharg on 16/11/2012.
//
//  Ported to Swift in P6b. The superclass (LDrawContainer) is still ObjC.
//  LDrawLSynth.h keeps the LSynthParserStateT enum (types only).
//
//==============================================================================

import AppKit
import OpenGL.GL

// Regular expressions (formerly RegexKitLite).
//
// RegexKitLite's -isMatchedByRegex: and -arrayOfCaptureComponentsMatchedByRegex: ran the pattern through ICU
// with no options over the whole string, as an unanchored search. NSRegularExpression with options 0 is the
// same ICU engine with the same defaults. Compiled patterns are cached, as RegexKitLite did; parsing can run
// on more than one thread, so the cache is locked.

private enum Pattern {
	static let begin			= "0\\s+SYNTH\\s+BEGIN\\s+(\\S+?)\\s+(\\S+)"
	static let beginLine		= "0\\s+SYNTH\\s+BEGIN\\s+\\S+?\\s+\\S+"
	static let end				= "0\\s+SYNTH\\s+END"
	static let showHide			= "0\\s+SYNTH\\s+(?:SHOW|HIDE)"
	static let synthesizedBegin	= "0\\s+SYNTH\\s+SYNTHESIZED\\s+BEGIN"
	static let synthesizedEnd	= "0\\s+SYNTH\\s+SYNTHESIZED\\s+END"
	static let direction		= "0\\s+SYNTH\\s+(INSIDE|OUTSIDE|CROSS)"
	static let directionWord	= "(INSIDE|OUTSIDE|CROSS)"
	static let partLine			= "^1\\s+"
	static let whitespaceOnly	= "^\\s+$"
}

//---------- LSynthRegex() ----------------------------------------[static]--
private enum LSynthRegex {
	private static let lock = NSLock()
	nonisolated(unsafe) private static var cache: [String: NSRegularExpression] = [:]

	static func regex(_ pattern: String) -> NSRegularExpression? {
		lock.lock()
		defer { lock.unlock() }

		if let regex = cache[pattern] {
			return regex
		}
		// (The patterns are constants that compile; a nil here would have raised
		// in the ObjC, on -setObject:nil.)
		let regex = try? NSRegularExpression(pattern: pattern, options: [])
		cache[pattern] = regex
		return regex
	}
}

//---------- LSynthIsMatchedByRegex() -----------------------------[static]--
// Was -[NSString isMatchedByRegex:]: YES if the pattern matches anywhere in the string. (nil -> NO, as
// messaging nil did.)
private func LSynthIsMatchedByRegex(_ string: NSString?, _ pattern: String) -> Bool {
	guard let string, let regex = LSynthRegex.regex(pattern) else {
		return false
	}

	return regex.rangeOfFirstMatch(in: string as String,
								   options: [],
								   range: NSMakeRange(0, string.length)).location != NSNotFound
}

//---------- LSynthCaptureComponents() ----------------------------[static]--
// Was -[NSString arrayOfCaptureComponentsMatchedByRegex:]: one array per match, each holding the whole match
// followed by every capture group; a group that took no part in the match is @"" (RegexKitLite's rule).
private func LSynthCaptureComponents(_ string: NSString?, _ pattern: String) -> [[NSString]] {
	var matches: [[NSString]] = []

	guard let string, let regex = LSynthRegex.regex(pattern) else {
		return matches
	}

	for match in regex.matches(in: string as String, options: [], range: NSMakeRange(0, string.length)) {
		var components: [NSString] = []
		components.reserveCapacity(match.numberOfRanges)

		for group in 0..<match.numberOfRanges {
			let range = match.range(at: group)
			components.append(range.location == NSNotFound ? "" : string.substring(with: range) as NSString)
		}
		matches.append(components)
	}
	return matches
}

/// -isEqualToString: with an object from a dictionary (UTF-16 units; nil or a non-string answers NO).
private func isEqualToString(_ string: String?, _ other: Any?) -> Bool {
	guard let string, let other = other as? String else {
		return false
	}
	return (string as NSString).isEqual(to: other)
}

/// -integerValue sent to an object from a dictionary (nil answered 0).
private func integerValue(_ object: Any?) -> Int {
	return (object as AnyObject?)?.integerValue ?? 0
}

/// -redComponent, -greenComponent and -blueComponent raise unless the colour is a component-based RGB colour
/// (catalog, pattern, grey and CMYK colours raise; checked against 20 kinds of NSColor, also after an
/// NSArchiver round trip).
private func componentsWouldRaise(_ color: NSColor) -> Bool {
	return !(color.type == .componentBased && color.colorSpace.colorSpaceModel == .rgb)
}


@objc(LDrawLSynth)
final class LDrawLSynth: LDrawContainer, LDrawColorable, LDrawMovableDirective {

	// Stored defaults are nil/literals: -[LDrawDirective initWithLines:...] re-sends
	// -init mid-parse (L104); -init allocates.
	private var synthesizedParts: NSMutableArray!	= nil
	/// The synthesized parts this block registered with as an observer (parse only; copies and decoded
	/// blocks don't register). deinit unregisters from exactly these.
	private var observedSynthesizedParts = Set<ObjectIdentifier>()
	private var synthType: String?					= nil
	private var lsynthClassValue: Int32				= 0
	private var color: LDrawColor?					= nil
	private var hidden								= false
	private var subdirectiveSelectedValue			= false
	private var cachedBounds: Box3					= Box3()	// cached bounds of the enclosed directives

	/// GLfloat glTransformation[16]: never written, so all zeros.
	private static let glTransformation = [GLfloat](repeating: 0, count: 16)


	// MARK: - Initialization

	//========== init ==============================================================
	//
	// Purpose:		Creates a new container with absolutely nothing in it, but
	//				ready to receive objects.
	//
	//==============================================================================
	@objc(init)
	override init() {
		super.init()

		synthesizedParts	= NSMutableArray()
		synthType			= ""
		color				= LDrawColor()

		cachedBounds = InvalidBox
		invalCache(.CacheFlagBounds)

		registerForNotifications()

	}//end init


	//========== registerForNotifications ==========================================
	//
	// Purpose:		The observers -init registers.
	//
	//==============================================================================
	private func registerForNotifications() {
		// Observe changes in selection display options
		NotificationCenter.default.addObserver(self,
											   selector: #selector(selectionDisplayOptionsDidChange(_:)),
											   name: .LSynthSelectionDisplayDidChange,
											   object: nil)

		// Observe requests for resynthesis
		NotificationCenter.default.addObserver(self,
											   selector: #selector(requiresResynthesis(_:)),
											   name: .LSynthResynthesisRequired,
											   object: nil)
	}


	//========== initWithLines:inRange: ============================================
	//
	// Purpose:		As -[LDrawDirective initWithLines:inRange:]: no parent group.
	//
	//==============================================================================
	@objc(initWithLines:inRange:)
	override convenience init!(lines: [NSObject]!, in range: NSRange) {
		self.init(lines: lines, in: range, parentGroup: nil)

	}//end initWithLines:inRange:


	//========== initWithLines:inRange:parentGroup: ================================
	//
	// Purpose:		Initializes the synthesized part with the supplied range of lines
	//
	// LSynth format is
	//
	// 0 SYNTH BEGIN <SYNTH_TYPE> <COLOR_CODE>
	// 0 SYNTH SHOW
	// 1 <CONSTRAINT PART>
	// 0 SYNTH INSIDE/OUTSIDE
	// ...
	//
	// <OPTIONALLY:>
	// 0 SYNTH SYNTHESIZED BEGIN
	// 1 <SYNTHESIZED PART SPEC>
	// ...
	// 0 SYNTH SYNTHESIZED END
	// 0 SYNTH END
	//
	// Notes:		The ObjC sent [self init] and then [super initWithLines:...],
	//				whose -[LDrawDirective initWithLines:...] sends -init again: two
	//				-inits, so the notification observers were registered twice
	//				(KNOWN-BUGS S32). Here super's -init is the only one, and the
	//				second registration is made explicitly.
	//
	//==============================================================================
	@objc(initWithLines:inRange:parentGroup:)
	override init!(lines: [NSObject]!, in range: NSRange, parentGroup: dispatch_group_t?) {
		var parserState: LSynthParserStateT	= .PARSER_READY_TO_PARSE
		// NSRange's fields are NSUInteger in ObjC: unsigned, wrapping arithmetic.
		var lineIndex: UInt					= UInt(bitPattern: range.location)
		let rangeMax: UInt					= lineIndex &+ UInt(bitPattern: range.length)

		// (nil when there are no lines: the ObjC then read its ivars through a
		// nil self and crashed; see KNOWN-BUGS BUG-062.)
		super.init(lines: lines, in: range, parentGroup: parentGroup)
		registerForNotifications() // Basic initialisation, not related to parsing (the first -init)

		let lineArray = lines! as NSArray

		while lineIndex < rangeMax {
			// P6b: ObjC raised here (-objectAtIndex: past the end of the lines);
			// see KNOWN-BUGS BUG-062
			guard lineIndex < UInt(lineArray.count) else {
				return nil
			}
			let currentLine = lineArray.object(at: Int(lineIndex)) as? NSString

			//
			// '0 SYNTH' directives
			//

			// 0 SYNTH BEGIN <SYNTH_TYPE> <COLOR>
			if LSynthIsMatchedByRegex(currentLine, Pattern.begin) &&
				parserState == .PARSER_READY_TO_PARSE {

				let paramMatches = LSynthCaptureComponents(currentLine, Pattern.begin)

				let type		= paramMatches[0][1] as String
				let synthColor	= paramMatches[0][2]

				setLsynthType(type)
				// (LDrawColorT) of -integerValue: truncated to int.
				setLDrawColor(ColorLibrary.shared()?.color(forCode: LDrawColorT(rawValue: Int32(truncatingIfNeeded: synthColor.integerValue))))

				LDrawApplication.shared().lsynthConfiguration().setLSynthClassForDirective(self, withType: type)
				parserState = .PARSER_PARSING_BEGUN
			}

			// 0 SYNTH END - Synthesized parts may or may not be present
			else if LSynthIsMatchedByRegex(currentLine, Pattern.end) &&
						(parserState == .PARSER_PARSING_CONSTRAINTS ||
						 parserState == .PARSER_SYNTHESIZED_FINISHED) {
				parserState = .PARSER_FINISHED
			}

			// 0 SYNTH SHOW or
			// 0 SYNTH HIDE
			else if LSynthIsMatchedByRegex(currentLine, Pattern.showHide) &&
						parserState == .PARSER_PARSING_BEGUN {
				parserState = .PARSER_PARSING_CONSTRAINTS
			}

			// 0 SYNTH SYNTHESIZED BEGIN - start of synthesized constraints
			else if LSynthIsMatchedByRegex(currentLine, Pattern.synthesizedBegin) &&
						parserState == .PARSER_PARSING_CONSTRAINTS {
				parserState = .PARSER_PARSING_SYNTHESIZED
			}

			// 0 SYNTH SYNTHESIZED BEGIN - end of synthesized constraints
			else if LSynthIsMatchedByRegex(currentLine, Pattern.synthesizedEnd) &&
						parserState == .PARSER_PARSING_SYNTHESIZED {
				parserState = .PARSER_SYNTHESIZED_FINISHED
			}

			// 0 SYNTH INSIDE or
			// 0 SYNTH OUTSIDE or
			// 0 SYNTH CROSS
			else if parserState == .PARSER_PARSING_CONSTRAINTS &&
						LSynthIsMatchedByRegex(currentLine, Pattern.direction) {

				// (The line matched the direction pattern above, so this word pattern matches too.)
				let direction = LSynthCaptureComponents(currentLine, Pattern.directionWord)[0][0] as String
				let directive = LDrawLSynthDirective()
				directive.setStringValue(direction)
				subdirectives().add(directive)
				directive.setEnclosing(self)
				directive.add(self)
			}

			//
			// '1 XXX' Part directives - constraints or synthesized parts
			//

			else if LSynthIsMatchedByRegex(currentLine, Pattern.partLine) &&
						(parserState == .PARSER_PARSING_BEGUN ||
						 parserState == .PARSER_PARSING_CONSTRAINTS ||
						 parserState == .PARSER_PARSING_SYNTHESIZED) {

				// Either way, create a part
				// (A Nil class answered a zero range and a nil directive: messaging Nil.)
				let CommandClass = LDrawUtilities.classForDirectiveBeginning(withLine: currentLine as String?) as? LDrawDirective.Type
				let commandRange = CommandClass?.rangeOfDirectiveBeginning(at: lineIndex,
																		   inLines: lines,
																		   maxIndex: rangeMax &- 1)
					?? NSMakeRange(0, 0)

				let newDirective = CommandClass?.directive(lines: lines, in: commandRange, parentGroup: parentGroup)
				newDirective?.setEnclosing(self)
				newDirective?.add(self)

				// Add our part in the correct place
				if parserState == .PARSER_PARSING_CONSTRAINTS {
					newDirective?.setIconName(determineIconName(newDirective))
					// P6b: ObjC raised here (-addObject:nil: a constraint part that
					// failed to parse); see KNOWN-BUGS BUG-063
					guard let newDirective else {
						return nil
					}
					subdirectives().add(newDirective)
				}

				else if parserState == .PARSER_PARSING_SYNTHESIZED {
					// P6b: ObjC raised here (-addObject:nil: a synthesized part
					// that failed to parse); see KNOWN-BUGS BUG-063
					guard let newDirective else {
						return nil
					}
					synthesizedParts.add(newDirective)
					observedSynthesizedParts.insert(ObjectIdentifier(newDirective))
				}

			}

			//
			// Unrecognized or inappropriate directive at this point
			//

			else {
				NSLog("Unexpected line in LSynth definition at line %lu: %@ (state: %i)",
					  lineIndex &+ 1, currentLine ?? ("(null)" as NSString), parserState.rawValue)
			}

			lineIndex &+= 1
		}

		// If we've read in synthesized parts or don't have any constraints then don't initially synthesize
		if synthesizedParts.count == 0 && (allEnclosedElements()?.count ?? 0) > 0 {
			invalCache(.ContainerInvalid)
		}

		NotificationCenter.default.post(name: NSNotification.Name(LDrawDirectiveDidChangeNotification), object: self)

	}//end initWithLines:inRange:


	//========== lineIsLSynthBeginning: ===========================================
	//
	// Purpose:		Returns if line is a 0 SYNTH START
	//
	//==============================================================================
	@objc(lineIsLSynthBeginning:)
	class func lineIsLSynthBeginning(_ line: String!) -> Bool {
		if LSynthIsMatchedByRegex(line as NSString?, Pattern.beginLine) {
			return true
		}
		return false
	} //end lineIsLSynthBeginning:


	//========== lineIsLSynthTerminator: ==========================================
	//
	// Purpose:		Returns if line is a 0 SYNTH END or 0 SYNTH PART (which are single
	//              line directives)
	//
	//==============================================================================
	@objc(lineIsLSynthTerminator:)
	class func lineIsLSynthTerminator(_ line: String!) -> Bool {
		if LSynthIsMatchedByRegex(line as NSString?, Pattern.end) {
			return true
		}
		return false
	} //end lineIsLSynthTerminator:


	//---------- rangeOfDirectiveBeginningAtIndex:inLines:maxIndex: ------[static]--
	//
	// Purpose:		Returns the range from the beginning to the end of the step.
	//              i.e. 0 SYNTH END
	//
	// Notes:		Index arithmetic is NSUInteger as in ObjC (wrapping operators).
	//
	//------------------------------------------------------------------------------
	@objc(rangeOfDirectiveBeginningAtIndex:inLines:maxIndex:)
	override class func rangeOfDirectiveBeginning(at index: UInt, inLines lines: [NSObject]!, maxIndex: UInt) -> NSRange {
		let lineArray			= lines as NSArray?
		var counter: UInt		= 0
		let testMax: UInt		= index &+ (maxIndex &- index &+ 1)	// NSMaxRange(testRange)
		var synthLength: Int	= 0

		// (Messaging a nil array answered nil, which matches nothing.)
		if let lineArray {
			// P6b: ObjC raised here (-objectAtIndex: past the end of the lines);
			// see KNOWN-BUGS BUG-064
			guard index < UInt(lineArray.count) else {
				return NSMakeRange(Int(bitPattern: index), synthLength)
			}
			var currentLine = lineArray.object(at: Int(index)) as? NSString
			if LSynthIsMatchedByRegex(currentLine, Pattern.beginLine) {

				// Find the last line in the synth definition: 0 SYNTH END
				counter = index &+ 1
				while counter < testMax {
					// P6b: ObjC raised here (-objectAtIndex: past the end of the
					// lines: a maxIndex past them); see KNOWN-BUGS BUG-064
					guard counter < UInt(lineArray.count) else {
						break
					}
					currentLine = lineArray.object(at: Int(counter)) as? NSString
					synthLength += 1

					if lineIsLSynthTerminator(currentLine as String?) {
						// Nothing more to parse. Stop.
						synthLength += 1
						break
					}
					counter &+= 1
				}
			}
		}

		return NSMakeRange(Int(bitPattern: index), synthLength)

	}//end rangeOfDirectiveBeginningAtIndex:inLines:maxIndex:


	//========== initWithCoder: ====================================================
	//
	// Purpose:		Reads a representation of this object from the given coder,
	//				which is assumed to always be a keyed decoder. This allows us to
	//				read and write LDraw objects as NSData.
	//
	// Notes:		The ObjC sent [self init] first; -[LDrawDirective initWithCoder:]
	//				doesn't, so that -init's work is repeated here.
	//
	//==============================================================================
	@objc(initWithCoder:)
	required init?(coder decoder: NSCoder) {
		// Container Coder initialization.  This repopulates our contained objects
		super.init(coder: decoder)

		// Initialize the object.  We'll have somewhere to synthesize into.
		synthesizedParts	= NSMutableArray()
		synthType			= ""
		color				= LDrawColor()
		cachedBounds		= InvalidBox
		invalCache(.CacheFlagBounds)
		registerForNotifications()

		// Reinitialize LSynth-specific attributes
		setLsynthClass(decoder.decodeCInt(forKey: "lsynthClass"))
		setLsynthType(decoder.decodeObject(forKey: "synthType") as? String)
		setLDrawColor(decoder.decodeObject(forKey: "color") as? LDrawColor)

		// Constraints' icons should have been encoded/decoded correctly so we do
		// nothing in that respect.

		// Ask for resynthesis since we don't preserve synthesized parts during a copy/paste
		invalCache(.ContainerInvalid)

	}//end initWithCoder:


	//========== encodeWithCoder: ==================================================
	//
	// Purpose:		Writes a representation of this object to the given coder,
	//				which is assumed to always be a keyed decoder. This allows us to
	//				read and write LDraw objects as NSData.
	//
	//              We don't store synthesized parts since they'll be recreated when
	//              we initWithCoder.
	//
	//==============================================================================
	@objc(encodeWithCoder:)
	override func encode(with encoder: NSCoder) {
		// Encode container-related stuff: containedObjects etc.
		super.encode(with: encoder)

		encoder.encodeCInt(lsynthClassValue, forKey: "lsynthClass")
		encoder.encode(synthType as NSString?, forKey: "synthType")
		encoder.encode(color, forKey: "color")

	}//end encodeWithCoder:


	// MARK: - Display

	//========== inspectorClassName ================================================
	//
	// Purpose:		Returns the name of the class used to inspect this one.
	//
	//==============================================================================
	@objc(inspectorClassName)
	override func inspectorClassName() -> String! {
		"InspectionLSynth"

	}//end inspectorClassName


	// MARK: - Directives

	//========== insertDirective:atIndex: ==========================================
	//
	// Purpose:		Inserts the new directive into the step.
	//
	//==============================================================================
	@objc(insertDirective:atIndex:)
	override func insert(_ directive: LDrawDirective!, at index: Int) {
		setSelected(false) // Explicitly deselect ourselves.  The newly added constraint gets selected.

		// Pick a badge icon depending on the LSynth class (band or hose)
		directive?.setIconName(determineIconName(directive))

		// P6b: ObjC raised here (-[NSMutableArray insertObject:atIndex:] in
		// LDrawContainer, with a nil directive or an index past the end); see
		// KNOWN-BUGS BUG-065
		// (A nil array, only from an archive without children, raised nothing.)
		let count = subdirectives()?.count ?? Int.max
		guard directive != nil, index >= 0, index <= count else {
			return
		}
		super.insert(directive, at: index)
		invalCache([.CacheFlagBounds, .DisplayList, .ContainerInvalid])

	}//end insertDirective:atIndex:


	//========== removeDirective: ==================================================
	//
	// Purpose:		Remove a contained directive (constraint etc.) and resynthesize
	//
	//==============================================================================
	@objc(removeDirective:)
	override func remove(_ doomedDirective: LDrawDirective!) {
		// We can leave removal to the base class
		super.remove(doomedDirective)

		// TODO: Should we select the constraint at the previous index?
		setSubdirectiveSelected(false)
		setSelected(false) // remove ourselves from the selection so that we can be selected by the user.
		invalCache(.ContainerInvalid)

		NotificationCenter.default.post(name: NSNotification.Name(LDrawDirectiveDidChangeNotification), object: self)
	}


	//========== draw:viewScale:parentColor: =======================================
	//
	// Purpose:		Draw the synthesized part.
	//
	//==============================================================================
	@objc(drawSelf:)
	override func drawSelf(_ renderer: (any LDrawRenderer)!) {
		let constraints = subdirectives()

		if hidden == false {
			// Draw each constraint, if:
			if isSelected() == true ||								// We're selected
				subdirectiveSelectedValue != false ||				// A subdirective (constraint) is selected
				lsynthClassValue == LSynthClassT.LSYNTH_BAND.rawValue ||	// We're a Band, so show constraints regardless
				(lsynthClassValue == LSynthClassT.LSYNTH_PART.rawValue &&	// We're a Band PART
				 partClass() == LSynthClassT.LSYNTH_BAND.rawValue)
			{
				if let constraints {
					for case let currentDirective as LDrawDirective in constraints {
						currentDirective.drawSelf(renderer)
					}
				}
			}

			// Resynthesize if we've been invalidated (by e.g. any of our constraints moving)
			// This is the only place we invoke synthesis.  While it may incur a small delay in drawing
			// it's lazy (in a good way), and means resynthesis only occurs when we actually need it.
			if revalCache(.ContainerInvalid) == .ContainerInvalid {
				// (Stops where the ObjC raised: BUG-066, BUG-029.)
				guard synthesizeParts() else {
					return
				}
				guard recolorSynthesizedParts(isSelected() || subdirectiveSelectedValue == true) else {
					return
				}
			}

			// Draw any synthesized parts as well
			if let synthesizedParts {
				for case let currentDirective as LDrawDirective in synthesizedParts {
					currentDirective.drawSelf(renderer)
				}
			}
		}

	}//end drawSelf:


	//========== hitTest:transform:viewScale:boundsOnly:creditObject:hits: =======
	//
	// Purpose:		Hit-test the geometry.
	//
	//==============================================================================
	@objc(hitTest:transform:viewScale:boundsOnly:creditObject:hits:)
	override func hitTest(_ pickRay: Ray3, transform: Matrix4, viewScale scaleFactor: Float, boundsOnly: Bool,
						  creditObject: Any!, hits: NSMutableDictionary!) {
		if hidden == false {
			let steps		= subdirectives() // i.e. constraints
			var counter		= 0

			// Hit test the constraints first since this will be the quicker test
			while counter < (steps?.count ?? 0) {
				let currentDirective = steps!.object(at: counter) as! LDrawDirective
				currentDirective.hitTest(pickRay,
										 transform: transform,
										 viewScale: scaleFactor,
										 boundsOnly: boundsOnly,
										 creditObject: currentDirective,
										 hits: hits)
				counter += 1
			}

			// Now do the synthesized pieces.  We take the credit.  Thangyouverehmuch.
			if let synthesizedParts {
				for case let part as LDrawDirective in synthesizedParts {
					part.hitTest(pickRay,
								 transform: transform,
								 viewScale: scaleFactor,
								 boundsOnly: boundsOnly,
								 creditObject: self,
								 hits: hits)
				}
			}
		}
	}//end hitTest:transform:viewScale:boundsOnly:creditObject:hits:


	//========== boxTest:transform:viewScale:boundsOnly:creditObject:hits: =======
	//
	// Purpose:		Check for intersections with screen-space geometry.
	//
	//==============================================================================
	@objc(boxTest:transform:boundsOnly:creditObject:hits:)
	override func boxTest(_ bounds: Box2, transform: Matrix4, boundsOnly: Bool, creditObject: Any!, hits: NSMutableSet!) -> Bool {
		let commands		= subdirectives()
		let commandCount	= commands?.count ?? 0
		var counter			= 0

		// Do constraints
		while counter < commandCount {
			let currentDirective = commands!.object(at: counter) as! LDrawDirective
			if currentDirective.boxTest(bounds,
										transform: transform,
										boundsOnly: boundsOnly,
										creditObject: self,
										hits: hits) {
				if creditObject != nil {
					return true
				}
			}
			counter += 1
		}

		// Also check synthesized parts
		if let synthesizedParts {
			for case let part as LDrawDirective in synthesizedParts {
				if part.boxTest(bounds,
								transform: transform,
								boundsOnly: boundsOnly,
								creditObject: self,
								hits: hits) {
					if creditObject != nil {
						return true
					}
				}
			}
		}

		return false
	}//end boxTest:transform:viewScale:boundsOnly:creditObject:hits:


	//========== depthTest:inBox:transform:creditObject:bestObject:bestDepth:=======
	//
	// Purpose:		depthTest finds the closest primitive (in screen space)
	//				overlapping a given point, as well as its device coordinate
	//				depth.
	//==============================================================================
	@objc(depthTest:inBox:transform:creditObject:bestObject:bestDepth:)
	override func depthTest(_ testPt: Point2, inBox bounds: Box2, transform: Matrix4, creditObject: Any!,
							bestObject: AutoreleasingUnsafeMutablePointer<AnyObject?>!,
							bestDepth: UnsafeMutablePointer<Float>!) {
		let commands		= subdirectives()
		let commandCount	= commands?.count ?? 0
		var counter			= 0

		while counter < commandCount {
			let currentDirective = commands!.object(at: counter) as! LDrawDirective
			currentDirective.depthTest(testPt,
									   inBox: bounds,
									   transform: transform,
									   creditObject: creditObject,
									   bestObject: bestObject,
									   bestDepth: bestDepth)
			counter += 1
		}

		// Now do the synthesized pieces.  We take the credit.
		if let synthesizedParts {
			for case let part as LDrawDirective in synthesizedParts {
				part.depthTest(testPt,
							   inBox: bounds,
							   transform: transform,
							   creditObject: self,
							   bestObject: bestObject,
							   bestDepth: bestDepth)
			}
		}

	}//end depthTest:inBox:transform:creditObject:bestObject:bestDepth:


	//========== write =============================================================
	//
	// Purpose:		Write out all the commands in the part
	//
	//==============================================================================
	@objc(write)
	override func write() -> String! {
		let written				= NSMutableString()
		let CRLF: String		= NSString.crlf()
		let lsynthVisibility	= "SHOW"
		let constraints			= subdirectives()
		var numberCommands		= 0
		var counter				= 0
		let userDefaults		= UserDefaults.standard

		// Start

		// ("%@" printed a nil type as "(null)"; a nil colour's code was 0.)
		written.append("0 SYNTH BEGIN \(lsynthType() ?? "(null)") \(color?.colorCode().rawValue ?? 0)\(CRLF)")
		written.append("0 SYNTH \(lsynthVisibility)\(CRLF)")

		numberCommands = constraints?.count ?? 0
		while counter < numberCommands {
			let currentCommand = constraints!.object(at: counter) as! LDrawDirective
			// P6b: ObjC raised here (-appendString:nil: a constraint whose write
			// is nil); see KNOWN-BUGS BUG-065
			guard let commandString = currentCommand.write() else {
				return nil
			}
			written.append(commandString)
			written.append(CRLF)
			counter += 1
		}

		// Write out synthesized parts, if there are any to write out
		// (integerForKey: compared with YES, so only 1 writes them.)
		if (synthesizedParts?.count ?? 0) > 0
			&& userDefaults.integer(forKey: LSYNTH_SAVE_SYNTHESIZED_PARTS_KEY) == 1 {
			written.append("0 SYNTH SYNTHESIZED BEGIN")
			written.append(CRLF)
			for case let part as LDrawPart in synthesizedParts {
				// Parts aren't smart enough to know that they're temporarily coloured differently
				// during Synth part selection, so we force the parent color in.  It's reset when the
				// part selection changes, anyway.
				part.setLDrawColor(color)
				// P6b: ObjC raised here (-appendString:nil); see KNOWN-BUGS
				// BUG-065
				guard let partString = part.write() else {
					return nil
				}
				written.append(partString)
				written.append(CRLF)
			}
			written.append("0 SYNTH SYNTHESIZED END")
			written.append(CRLF)
		}
		// End
		written.append("0 SYNTH END")
		written.append(CRLF)

		return written as String
	}//end write


