	// MARK: - <LDrawMovableElement> protocol methods

	//========== displacementForNudge: =============================================
	//
	// Purpose:		Determine the displacement for a specific nudge.  We rely on the
	//              first subdirective that can help; all subdirectives will move
	//              same amount.
	//
	//==============================================================================
	@objc(displacementForNudge:)
	func displacement(forNudge nudgeVector: Vector3) -> Vector3 {
		if let commands = subdirectives() {
			for directive in commands {
				// (LDrawDrawableElement declares <LDrawMovableDirective>, so the
				// -conformsToProtocol: test always passed for it.)
				if let drawable = directive as? LDrawDrawableElement {
					return drawable.displacement(forNudge: nudgeVector)
				}
			}
		}
		let v = Vector3(x: 0, y: 0, z: 0)
		return v

	}


	//========== moveBy: ===========================================================
	//
	// Purpose:		Passes a movement request down to its subdirectives
	//
	// Optimisation: move all synthesized elements as well to save a resynth
	//
	//==============================================================================
	@objc(moveBy:)
	func move(by moveVector: Vector3) {
		// pass on the nudge to drawable subdirectives
		if let commands = subdirectives() {
			for constraint in commands {
				if let movable = constraint as? LDrawMovableDirective {
					movable.move(by: moveVector)
				}
			}
		}
	}//end moveBy:


	// MARK: - Utility functions

	//========== synthesize ========================================================
	//
	// Purpose:	Synthesizes the part using LSynth
	//
	// TODO: multithread/background
	//
	//==============================================================================
	@objc(synthesize)
	func synthesize() {
		_ = synthesizeParts()
	}

	/// -synthesize; false where the ObjC raised (BUG-066), so callers here stop too.
	private func synthesizeParts() -> Bool {
		//NSLog(@"SYNTHESIZE");

		// Modifies the constraints to provide automatic OUTSIDE/INSIDE determination for
		// constraints inside the convex hull.  Dig down for more details.
		let doAutoHull = true // Placeholder until we make it a configurable setting
		if doAutoHull == true && lsynthClassValue == LSynthClassT.LSYNTH_BAND.rawValue {
			// TODO: Turned off while the Inspector code is fleshed out
			//[self doAutoHullOnBand];
		}

		// Clean up first
		// (P6b: stop observing the parse-registered parts being dropped, so one that
		// outlives this block can't say goodbye to it after it is freed; see deinit.)
		unregisterFromSynthesizedParts()
		synthesizedParts?.removeAllObjects()

		var input = ""

		// Path to lsynth.  If it's unset or whitespace use the built-in default
		let userDefaults	= UserDefaults.standard
		let executablePath	= userDefaults.string(forKey: LSYNTH_EXECUTABLE_PATH_KEY) as NSString?
		var configPath		= userDefaults.string(forKey: LSYNTH_CONFIGURATION_PATH_KEY) as NSString?
		var lsynthPath: String?
		if (executablePath?.length ?? 0) == 0 || LSynthIsMatchedByRegex(executablePath, Pattern.whitespaceOnly) {
			lsynthPath = Bundle.main.path(forAuxiliaryExecutable: "lsynthcp")

			// The built-in lsynthcp looks for lsynth.mpd beside its executable unless
			// told otherwise. Data files can't live in Contents/MacOS of a signed app,
			// so point it explicitly at the identical copy in Resources.
			if (configPath?.length ?? 0) == 0 || LSynthIsMatchedByRegex(configPath, Pattern.whitespaceOnly) {
				configPath = Bundle.main.path(forResource: "lsynth", ofType: "mpd") as NSString?
			}
		}
		else {
			lsynthPath = executablePath as String?
		}

		// We run LSynth as follows:
		// - Create an LDraw file in memory
		// - Setup the STDIN/OUT pipes and NSTask
		// - Launch task
		// - Write to LSynth's STDIN, read from its STDOUT
		// - Process the output (using LDrawDirective's parser) into synthesized parts

		// Create an LDraw file in memory
		// (A nil colour's code was 0.)
		let code: LDrawColorT = subdirectiveSelectedValue ? LDrawClear : (lDrawColor()?.colorCode() ?? LDrawColorT(rawValue: 0))
		input += "0 SYNTH BEGIN \(synthType ?? "(null)") \(code.rawValue)\n"
		input += "0 SYNTH \("SHOW")\n" // TODO: honour visibility?
		if let commands = subdirectives() {
			for case let part as LDrawDirective in commands {
				input += "\(part.write() ?? "(null)")\n"
			}
		}
		input += "0 SYNTH END\n"
		input += "0 STEP\n"

		// Setup the STDIN/OUT pipes and NSTask
		let task		= Process()
		let inPipe		= Pipe()
		let outPipe		= Pipe()
		let errorPipe	= Pipe()

		// Add custom configuration arguments if required
		var arguments: [String] = []
		if let configPath, configPath.length > 0 {
			arguments.append(contentsOf: ["-c", configPath as String])
		}
		arguments.append("-") // Our built-in LSynth accepts STDIN/STDOUT with this argument

		task.standardInput = inPipe
		task.standardOutput = outPipe
		task.standardError = errorPipe
		// P6b: ObjC raised here (-launch with no launch path); see KNOWN-BUGS
		// BUG-066
		guard let lsynthPath else {
			return false
		}
		task.executableURL = URL(fileURLWithPath: lsynthPath)
		task.arguments = arguments
		//    [task setArguments:[NSArray arrayWithObject:@"-"]]; // Our built-in LSynth accepts STDIN/STDOUT with this argument

		let inFile	= inPipe.fileHandleForWriting
		let outFile	= outPipe.fileHandleForReading
		_ = errorPipe.fileHandleForReading

		// Launch the task
		// P6b: ObjC raised here (-launch: a path that doesn't exist, isn't
		// executable, or is a directory); see KNOWN-BUGS BUG-066.
		// -run throws instead of raising.
		do {
			try task.run()
		}
		catch {
			return false
		}

		// Write the LSynth part to LSynth's STDIN
		// (-dataUsingEncoding:NSASCIIStringEncoding is nil for non-ASCII input, and
		// -writeData:nil wrote nothing.)
		// P6b: ObjC raised here (-writeData: or -closeFile on an I/O error, such as
		// EPIPE when lsynth has exited and SIGPIPE is ignored); see KNOWN-BUGS
		// BUG-066. These throw instead of raising.
		do {
			if let data = (input as NSString).data(using: String.Encoding.ascii.rawValue) {
				try inFile.write(contentsOf: data)
			}
			try inFile.close()
		}
		catch {
			return false
		}

		// Read standard error - causing a race condition?
//		NSMutableData *errorData = [[NSMutableData alloc] init];
//		...

		// Read the synthesized file back in from LSynth's STDOUT
		// (Was an -availableData loop up to the first empty read, i.e. to the end.)
		// P6b: ObjC raised here (-availableData on a read error); see KNOWN-BUGS
		// BUG-066. -readToEnd throws instead.
		let data: Data
		do {
			data = try outFile.readToEnd() ?? Data()
		}
		catch {
			return false
		}

		// (NSString's ASCII decoding; nil splits into no lines.)
		let lsynthOutput = NSString(data: data, encoding: String.Encoding.ascii.rawValue)

		// Split the output into lines
		let stringsArray = lsynthOutput?.components(separatedBy: CharacterSet.newlines) ?? []

		// Process the synthesized parts
		var extract = false

		for line in stringsArray {
			let nsLine		= line as NSString
			let startRange	= nsLine.range(of: "0 SYNTH SYNTHESIZED BEGIN")
			let partRange	= nsLine.range(of: "1")

			if extract == true && partRange.length > 0 && partRange.location == 0 {
				// (A Nil class, for an unknown line type such as "10", answered a nil directive.)
				let CommandClass = LDrawUtilities.classForDirectiveBeginning(withLine: line) as? LDrawDirective.Type
				let newDirective = CommandClass?.directive(lines: [nsLine],
														   in: NSMakeRange(0, 1),
														   parentGroup: nil)
				// P6b: ObjC raised here (-addObject:nil: an output line that didn't
				// parse); see KNOWN-BUGS BUG-066
				guard let newDirective else {
					return false
				}
				synthesizedParts?.add(newDirective)
			}
			else if extract == false && startRange.length > 0 {
				extract = true
			}
		}

		return true
	}


	//========== doAutoHullOnBand ==================================================
	//
	// Purpose:	Calculate the INSIDE/OUTSIDE directives automatically.
	//
	//          Based on calculating the convex hull of the constraints and inserting
	//          INSIDE/OUTSIDE directives appropriately.
	//
	// Notes:	Not called: its only call, in -synthesize, is commented out.
	//
	//==============================================================================
	@objc(doAutoHullOnBand)
	func doAutoHullOnBand() {
		guard let constraints = subdirectives() else {
			return
		}

		// clean out INSIDE/OUTSIDE directives
		var i = constraints.count - 1
		while i >= 0 {
			if constraints.object(at: i) is LDrawLSynthDirective {
				constraints.removeObject(at: i)
			}
			i -= 1
		}
		//NSLog(@"Cleaned subdirs: %@", [self subdirectives]);

		// Prepare the constraints for calculating the convex hull.
		// P6b: ObjC raised inside -prepareAutoHullData (see there); stop here too.
		guard let preparedData = prepareAutoHullData() else {
			return
		}

		// Determine the Convex Hull.  This is the meat.  After this we know
		// which constraints are really on the hull.  We respect their radii..
		ComputationalGeometry.doJarvisMarch(preparedData)

		//NSLog(@"Prepared Data After: %@", preparedData);

		// Reintegrate our hull-determined data.  We'll likely have multiple
		// points all on the hull, each associated with a single constraint.
		// This boils them down to a set of constraints on the hull.
		let hullConstraints = NSMutableSet()
		for case let point as NSDictionary in preparedData {
			if integerValue(point.object(forKey: "inHull")) == 1 {
				hullConstraints.add(point.object(forKey: "directive") as Any)
			}
		}
		//NSLog(@"hullConstraints: %@", hullConstraints);

		// Knowing which constraints are on the hull allows us to add
		// INSIDE/OUTSIDE constraints as we iterate over them.
		// We could modify the constraints in-place but recreating the
		// subdirectives array is simpler.
		let newConstraints = NSMutableArray()

		i = 0
		while i < constraints.count {
			let part		= constraints.object(at: i)
			let nextPart	= constraints.object(at: (i + 1) % constraints.count)

			// The first point is potentially a special case.  Handle it.
			// Not on the hull? Then prepend an OUTSIDE
			if i == 0 && !hullConstraints.contains(part) {
				let OUTSIDE = LDrawLSynthDirective()
				OUTSIDE.setStringValue("OUTSIDE")
				newConstraints.add(OUTSIDE)
			}

			// This part is on the hull (i.e. INSIDE the band) and the next part is
			// NOT on hull (i.e. OUTSIDE)
			if hullConstraints.contains(part) &&
				!hullConstraints.contains(nextPart) {
				// generate OUTSIDE
				let OUTSIDE = LDrawLSynthDirective()
				OUTSIDE.setStringValue("OUTSIDE")
				newConstraints.add(part)
				newConstraints.add(OUTSIDE)
			}

			// This part is not on the hull (i.e. OUTSIDE the band) and the next part IS
			// on hull (i.e. INSIDE)
			else if !hullConstraints.contains(part) &&
						hullConstraints.contains(nextPart) {
				// generate INSIDE
				let INSIDE = LDrawLSynthDirective()
				INSIDE.setStringValue("INSIDE")
				newConstraints.add(part)
				newConstraints.add(INSIDE)
			}

			// The constraint has the same hull membership as the next one so
			// no change of direction.  Just add it.
			else {
				newConstraints.add(part)
			}

			//NSLog(@"New Constraints: %@", newConstraints);
			i += 1
		}

		// Finally, update the constraints
		constraints.removeAllObjects()
		constraints.addObjects(from: newConstraints as! [Any])
	}


	//========== prepareAutoHullData ===============================================
	//
	// Purpose:	Prepare a datastructure containing points, directives etc., ready for
	//          calculating the convex hull.
	//
	// Notes:	Only -doAutoHullOnBand calls it, and that is never called.
	//
	//==============================================================================
	@objc(prepareAutoHullData)
	func prepareAutoHullData() -> NSMutableArray! {

		// Used for looking up constraint radii
		let config = LSynthConfiguration.sharedInstance()

		// P6b: ObjC raised here (-objectAtIndex:0 of a block with no
		// constraints, or -transformationMatrix sent to a direction directive,
		// which doesn't implement it); see KNOWN-BUGS BUG-067
		guard let constraints = subdirectives(), constraints.count > 0 else {
			return nil
		}
		var parts: [LDrawPart] = []
		for directive in constraints {
			guard let part = directive as? LDrawPart else {
				return nil
			}
			parts.append(part)
		}

		// Map each constraint to XY plane, based on the orientation of the first constraint
		// We build up details for each constraint in mappedPoints as we progress.
		// The inverse of the first constraint's transformation moves it back to (0,0,0).
		// The same inverse transform will do similar for the other constraints
		let mappedPoints		= NSMutableArray()
		let transform			= parts[0].transformationMatrix()
		let inverseTransform	= Matrix4Invert(transform)
		for part in parts {
			var transformed: Matrix4
			transformed = Matrix4Multiply(part.transformationMatrix(), inverseTransform)
			var t = TransformComponents()
			Matrix4DecomposeTransformation(transformed, &t)
			let radius = config?.constraintDefinition(for: part)?["radius"]
			let point = NSMutableDictionary(objects: [part,
													  NSNumber(value: t.translate.x),
													  NSNumber(value: t.translate.y),
													  NSNumber(value: Int32(truncatingIfNeeded: integerValue(radius))),
													  NSMutableArray()],
											forKeys: ["directive" as NSString, "x" as NSString, "y" as NSString,
													  "r" as NSString, "hullPoints" as NSString])
			mappedPoints.add(point)
		}
		//NSLog(@"Mapped Points: %@", mappedPoints);

		// Generate hull points by calculating "outside" tangents for each pair of
		// constraint-derived circles, e.g. ((0,1), (1,2), ..., (N,0)
		// Some of these will be on the inside of the convex hull but that's OK since the
		// convex hull calculation will discard them.
		// TODO: can we  take advantage of CCW ordering of constraints?
		var i = 0
		while i < mappedPoints.count {
			let j = (i + 1) % mappedPoints.count // next constraint, cyclical (N+1 -> 0)

			let circleI = mappedPoints.object(at: i) as! NSMutableDictionary
			let circleJ = mappedPoints.object(at: j) as! NSMutableDictionary
			let tangents = ComputationalGeometry.tangentBetweenCircle(circleI, andCircle: circleJ) as NSArray?
			if let tangents {
				// Tangents are between two circles (i.e. constraints)
				// add both outside tangent points for the current constraint
				let tangent0 = tangents.object(at: 0) as! NSArray
				let tangent1 = tangents.object(at: 1) as! NSArray
				let hullPointsI = circleI.object(forKey: "hullPoints") as! NSMutableArray
				let hullPointsJ = circleJ.object(forKey: "hullPoints") as! NSMutableArray

				hullPointsI.add(NSDictionary(objects: [tangent0.object(at: 0), tangent0.object(at: 1)],
											 forKeys: ["x" as NSString, "y" as NSString]))

				hullPointsI.add(NSDictionary(objects: [tangent1.object(at: 0), tangent1.object(at: 1)],
											 forKeys: ["x" as NSString, "y" as NSString]))

				// add both outside tangent points for the next constraint
				hullPointsJ.add(NSDictionary(objects: [tangent0.object(at: 2), tangent0.object(at: 3)],
											 forKeys: ["x" as NSString, "y" as NSString]))

				hullPointsJ.add(NSDictionary(objects: [tangent1.object(at: 2), tangent1.object(at: 3)],
											 forKeys: ["x" as NSString, "y" as NSString]))
			}

			//NSLog(@"Tangents: %@", tangents);
			i += 1
		}
		//NSLog(@"Mapped Points after tangent calc: %@", mappedPoints);

		// Prepare the mappedPoints for the Convex Hull algorithm
		// We create a dictionary for each hull point for each mappedPoint
		// We'll reintegrate later to decide which constraints are in or out
		// (in doAutoHullOnBand)
		let preparedData = NSMutableArray()
		for case let point as NSDictionary in mappedPoints {
			for case let coords as NSDictionary in (point.object(forKey: "hullPoints") as! NSArray) {
				//NSLog(@"Point: %@", coords);
				// TODO: check that int values are OK.  Prob. should use float?

				preparedData.add(NSMutableDictionary(objects: [point.object(forKey: "directive") as Any,
															   NSNumber(value: Int32(truncatingIfNeeded: integerValue(coords.object(forKey: "x")))),
															   NSNumber(value: Int32(truncatingIfNeeded: integerValue(coords.object(forKey: "y")))),
															   NSNumber(value: false)],
													 forKeys: ["directive" as NSString, "x" as NSString, "y" as NSString,
															   "inHull" as NSString]))
			}
		}
		//NSLog(@"Prepared Data: %@", preparedData);
		return preparedData
	}//end prepareAutoHullData


	//========== determineIconName: ================================================
	//
	// Purpose:		Determine the name of the constraint icon depending on the type
	//              of synthesized part.
	//
	//==============================================================================
	@objc(determineIconName:)
	func determineIconName(_ directive: LDrawDirective!) -> String! {
		// Hose
		if lsynthClassValue == LSynthClassT.LSYNTH_HOSE.rawValue {
			return "LSynthHoseConstraint"
		}

		// Band
		else if lsynthClassValue == LSynthClassT.LSYNTH_BAND.rawValue {
			return "LSynthBandConstraint"
		}

		// Part
		else if lsynthClassValue == LSynthClassT.LSYNTH_PART.rawValue {
			if partClass() == LSynthClassT.LSYNTH_HOSE.rawValue {
				return "LSynthHoseConstraint"
			}
			else if partClass() == LSynthClassT.LSYNTH_BAND.rawValue {
				return "LSynthBandConstraint"
			}
		}

		// Other?
		return "Brick"
	}//end determineIconName:


	//========== colorSelectedSynthesizedParts: ====================================
	//
	// Purpose:		Change the appearance of selected synthesized parts according
	//              to user preferences so that they can better see the object and
	//              its constraints.
	//
	//==============================================================================
	@objc(colorSelectedSynthesizedParts:)
	func colorSelectedSynthesizedParts(_ yesNo: Bool) {
		_ = recolorSynthesizedParts(yesNo)
	}

	/// -colorSelectedSynthesizedParts:; false where the ObjC raised (BUG-029), so callers here stop too.
	private func recolorSynthesizedParts(_ yesNo: Bool) -> Bool {
		let userDefaults	= UserDefaults.standard
		// (LSynthSelectionModeT) of -integerForKey:: truncated to int.
		let selectionMode	= Int32(truncatingIfNeeded: userDefaults.integer(forKey: LSYNTH_SELECTION_MODE_KEY))
		// a temporary RGBA color we create and manipulate. (Uninitialised in
		// the ObjC; zero here. Only an unknown selection mode left it unset.)
		var rgba			= [GLfloat](repeating: 0, count: 4)
		var theColor: LDrawColor? = LDrawColor() // an LDrawColor to set the part's color with

		// Is the part selected?
		if yesNo == true {

			// Modify the transparency, but use the object's existing color
			if selectionMode == Int32(TransparentSelection.rawValue) {
				color?.getRGBA(&rgba)
				rgba[3] = Float(userDefaults.integer(forKey: LSYNTH_SELECTION_TRANSPARENCY_KEY)) / 100
			}

			// Modify the color, with full opacity/no transparency
			else if selectionMode == Int32(ColoredSelection.rawValue) {
				let selectionColor = userDefaults.color(forKey: LSYNTH_SELECTION_COLOR_KEY)
				// P6b: ObjC raised here (-redComponent on a colour that isn't RGB,
				// such as the default systemRedColor); see KNOWN-BUGS BUG-029
				if let selectionColor, componentsWouldRaise(selectionColor) {
					return false
				}
				rgba[0] = Float(selectionColor?.redComponent ?? 0)
				rgba[1] = Float(selectionColor?.greenComponent ?? 0)
				rgba[2] = Float(selectionColor?.blueComponent ?? 0)
				rgba[3] = 1.0 // fully opaque
			}

			// Modify both color and transparency
			else if selectionMode == Int32(TransparentColoredSelection.rawValue) {
				let selectionColor = userDefaults.color(forKey: LSYNTH_SELECTION_COLOR_KEY)
				// P6b: ObjC raised here (-redComponent on a colour that isn't RGB,
				// such as the default systemRedColor); see KNOWN-BUGS BUG-029
				if let selectionColor, componentsWouldRaise(selectionColor) {
					return false
				}
				rgba[0] = Float(selectionColor?.redComponent ?? 0)
				rgba[1] = Float(selectionColor?.greenComponent ?? 0)
				rgba[2] = Float(selectionColor?.blueComponent ?? 0)
				rgba[3] = Float(userDefaults.integer(forKey: LSYNTH_SELECTION_TRANSPARENCY_KEY)) / 100
			}

			theColor?.setColorRGBA(&rgba)
		}

		// The part's not selected so use its actual color
		else {
			theColor = color
		}

		// Recolor the synthesized parts
		if let synthesizedParts {
			for case let part as LDrawPart in synthesizedParts {
				part.setLDrawColor(theColor)
			}
		}

		return true
	} //end colorSelectedSynthesizedParts:


	//========== transformationMatrix ==============================================
	//
	// Purpose:		Returns a two-dimensional (row matrix) representation of the
	//				part's transformation matrix.
	//
	//																+-       -+
	//				+-                           -+        +-     -+| a d g 0 |
	//				|a d g 0 b e h c f i 0 x y z 1|  -->   |x y z 1|| b e h 0 |
	//				+-                           -+        +-     -+| c f i 0 |
	//																| x y z 1 |
	//																+-       -+
	//					  OpenGL Matrix Format                 LDraw Matrix
	//				(flat column-major of transpose)              Format
	//
	//==============================================================================
	@objc(transformationMatrix)
	func transformationMatrix() -> Matrix4 {
		return LDrawLSynth.glTransformation.withUnsafeBufferPointer {
			Matrix4CreateFromGLMatrix4($0.baseAddress)
		}

	}//end transformationMatrix


	//========== acceptsDroppedDirective: ==========================================
	//
	// Purpose:		Returns YES if this container will accept a directive dropped on
	//              it.
	//
	//==============================================================================
	@objc(acceptsDroppedDirective:)
	override func acceptsDroppedDirective(_ directive: LDrawDirective!) -> Bool {
		// Only add valid parts as constraints; invalid ones are passed to our container
		// This arises if a synth part is selected and a part is dragged from the
		// part chooser to the view.
		if		((directive is LDrawPart) && LSynthConfiguration.sharedInstance().isLSynthConstraint(directive as? LDrawPart))
			||	(directive is LDrawLSynthDirective) {
			return true
		}
		return false
	}


	//========== cleanupAfterDrop ====================================================
	//
	// Purpose:		Called as part of a drag and drop operation.
	//              The argument indicates whether we were a donating parent or not.
	//              this in turn affect whether we should be selected.
	//
	// TODO: Should be a protocol
	//
	//==============================================================================
	@objc(cleanupAfterDropIsDonor:)
	func cleanupAfterDrop(isDonor: NSNumber!) {
		setSelected(false)

		// (-boolValue of nil answered NO.)
		if (isDonor?.boolValue ?? false) == false {
			setSubdirectiveSelected(true)
		}
	} //end cleanupAfterDrop


	//========== synthesizedPartsCount =============================================
	//
	// Purpose:		Returns the number of parts synthesized to create the shape.
	//
	//==============================================================================
	@objc(synthesizedPartsCount)
	func synthesizedPartsCount() -> CInt {
		// (NSUInteger returned as int: truncated.)
		Int32(truncatingIfNeeded: synthesizedParts?.count ?? 0)
	}


	//========== partClass =========================================================
	//
	// Purpose:		Returns the class of a part
	//              TODO: Optimise part class determination into a config dict and
	//              remove the loops.
	//
	// Notes:		Returns an LSynthClassT; as CInt, since any int was possible.
	//
	//==============================================================================
	@objc(partClass)
	func partClass() -> CInt {
		var partClass = lsynthClassValue

		if lsynthClassValue == LSynthClassT.LSYNTH_PART.rawValue {
			let partTypes = LSynthConfiguration.sharedInstance()?.getParts()

			// Loop over the parts from config, and when we find one matching ourselves
			// use that part's class.
			if let partTypes {
				for case let part as NSDictionary in partTypes {
					if isEqualToString(lsynthType(), part.value(forKey: "LSYNTH_TYPE")) {
						partClass = Int32(truncatingIfNeeded: integerValue(part.value(forKey: "LSYNTH_CLASS")))
						break
					}
				}
			}
		}
		else {
			// For some reason we've been called when we're not a Part so trust that
			// we have the correct class.
		}

		return partClass
	}


	// MARK: - Notifications

	//========== receiveMessage:who: ===============================================
	//
	// Purpose:		The things we observe call this when something one-time and
	//				eventful happens - we can respond if desired.
	//
	//==============================================================================
	@objc(receiveMessage:who:)
	override func receiveMessage(_ msg: MessageT, who observable: (any LDrawObservable)!) {
		// Typically if one of our child constraints changed we need to resynthesize
		if msg == .observedChanged {
			invalCache(.ContainerInvalid)
		}
	} //end receiveMessage:who:


	//========== selectionDisplayOptionsDidChange: =================================
	//
	// Purpose:		The selection style has changed, so we may need to redraw.
	//              We get here via a LSynthSelectionDisplayDidChangeNotification
	//              probably sent from the preferences controller.
	//
	//==============================================================================
	@objc(selectionDisplayOptionsDidChange:)
	func selectionDisplayOptionsDidChange(_ sender: Any!) {
		// (Stops where the ObjC raised: BUG-029.)
		guard recolorSynthesizedParts(isSelected() || subdirectiveSelectedValue) else {
			return
		}
		noteNeedsDisplay()
	} // end selectionDisplayOptionsDidChange:


	//========== requiresResynthesis: ==============================================
	//
	// Purpose:		LSynth parts need resynthesized explicitly for some reason.
	//              We get here via a LSynthResynthesisRequiredNotification
	//              probably sent from the preferences controller in response to an
	//              executable or config file change.
	//
	//==============================================================================
	@objc(requiresResynthesis:)
	func requiresResynthesis(_ sender: Any!) {
		// (Stops where the ObjC raised: BUG-066, BUG-029.)
		guard synthesizeParts() else {
			return
		}
		guard recolorSynthesizedParts(isSelected() || subdirectiveSelectedValue) else {
			return
		}
		noteNeedsDisplay()
	} // end requiresResynthesis:

	// MARK: - Destructor

	//========== deinit ========================================================
	//
	// Purpose:		Stop observing the synthesized parts. LDrawContainer's dealloc
	//				does this for the children (constraints); the synthesized parts
	//				are observed too (parse) but live in their own array, and the ObjC
	//				never unregistered from them: it relied on them dying with the
	//				block. Under Swift a part can outlive the block in an autorelease
	//				pool, and its -[LDrawDirective dealloc] then said goodbye to the
	//				freed block (P6b integration crash, found with NSZombieEnabled).
	//				Only parts this block registered with (observedSynthesizedParts):
	//				removing an unknown observer asserts.
	//
	//==========================================================================
	deinit {
		unregisterFromSynthesizedParts()
	}

	private func unregisterFromSynthesizedParts() {
		if let synthesizedParts, observedSynthesizedParts.isEmpty == false {
			for case let part as LDrawDirective in synthesizedParts
				where observedSynthesizedParts.contains(ObjectIdentifier(part)) {
				part.remove(self as LDrawObserver)
			}
		}
		observedSynthesizedParts.removeAll()
	}
}
